INSERT INTO reviews (product_id, user_name, rating, comment, location, verified) VALUES (1, 'Kavya Reddy', 5, 'The intricate craftsmanship and weight of this Kundan set is mesmerizing. Wore it for my reception and received endless compliments on the antique gold polish!', 'Dallas, TX', true);
